import{_ as t,c as s,o as a,ae as e}from"./chunks/framework.Bi6zybwU.js";const k=JSON.parse('{"title":"Image Lightbox Using Column Transform Value","description":"Image Lightbox Using Column Transform Value","frontmatter":{"title":"Image Lightbox Using Column Transform Value","description":"Image Lightbox Using Column Transform Value"},"headers":[],"relativePath":"guide/table-formatting/image-lightbox-using-column-transform-value.md","filePath":"guide/table-formatting/image-lightbox-using-column-transform-value.md"}'),n={name:"guide/table-formatting/image-lightbox-using-column-transform-value.md"};function l(o,i,h,r,g,p){return a(),s("div",null,[...i[0]||(i[0]=[e('<h1 id="image-lightbox-using-column-transform-value" tabindex="-1">Image Lightbox Using Column Transform Value <a class="header-anchor" href="#image-lightbox-using-column-transform-value" aria-label="Permalink to &quot;Image Lightbox Using Column Transform Value&quot;">​</a></h1><p>Users frequently want to import a table with an Image column from Google Sheets into <strong>Ninja</strong> <strong>Tables</strong>. When an image from that column is clicked, it opens in a lightbox with a darker background. There&#39;s already a &quot;<a href="https://ninjatables.com/docs/image-file-lightbox/" target="_blank" rel="noreferrer">Lightbox</a>&quot; data type option in Ninja Tables. So apply this to your table by following this simple guide.</p><h2 id="transform-image-url-into-image-lightbox" tabindex="-1">Transform Image URL into Image Lightbox <a class="header-anchor" href="#transform-image-url-into-image-lightbox" aria-label="Permalink to &quot;Transform Image URL into Image Lightbox&quot;">​</a></h2><p>A table from Google Sheets has been uploaded into Ninja Tables for demonstration purposes. This table offers data about numerous car models. It is divided into two columns: <strong>Name</strong> and <strong>Image</strong>. <img src="https://ninjatables.com/wp-content/uploads/2022/11/image-8.png" alt="image link in Google Sheets"></p><ul><li>In the image column, various image links/URL has been added.</li><li>Connect this <a href="https://ninjatables.com/docs/google-sheets-integration/" target="_blank" rel="noreferrer">Google Sheet</a> to Ninja Tables and the columns will be imported automatically. But the image links won&#39;t transform into images and neither open in a lightbox.</li><li>Now to convert this image link into an Image, first navigate to the <strong>Table Configuration</strong> tab. Then click on the <strong>Edit</strong> icon located on the right side of the <strong>Image</strong> column bar. There you will find an option called <strong><a href="https://ninjatables.com/docs/transform-value/" target="_blank" rel="noreferrer">Transform Value</a></strong>, click on that.</li><li>In the transform value field, add this code; this is quite a simple HTML code:</li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Image column Reference Shortcode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><p>Now turn this image link into an Image. Replace the text inside the quotations with the <strong>Column Shortcode</strong> of the Image column given in the <strong>Transform</strong> <strong>Value</strong> option.</p></li><li><p>So the code will ultimately look like this:</p></li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{row.image}}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li>Then click on the <strong>Update</strong> button to save the code. All the image URLs are shown as an image in the table.</li></ul><h3 id="image-with-lightbox" tabindex="-1">Image with Lightbox <a class="header-anchor" href="#image-with-lightbox" aria-label="Permalink to &quot;Image with Lightbox&quot;">​</a></h3><ul><li><p>To convert this image link into an <strong>Image Lightbox</strong>, add an HTML code in the Transform Value box.</p></li><li><p>In the transform value field, add this code; this is quite a simple HTML code:</p></li></ul><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Image Shortcode&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nt_lightbox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Image Shortcode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><ul><li><p>Now turn this image link into an Image Lightbox. Replace the <strong>Image Shortcode</strong> with the <strong>Column Shortcode</strong> of the Image column given in the Transform Value option.</p></li><li><p>A class named <strong>nt_lightbox</strong> also needs to be added inside the anchor tag. This class is used to transform the image URL into an Image Lightbox.</p></li></ul><p>So the code will ultimately look like this:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{row.image}}&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nt_lightbox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;{{row.image}}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><img src="https://ninjatables.com/wp-content/uploads/2022/10/table-configuration-01-scaled.webp" alt=""></p><ul><li><p>Then click on the <strong>Update</strong> button to save the code.</p></li><li><p>Next, go to the <strong>Table Design</strong> tab <strong>→</strong> click on the <strong>Other</strong> option. Then you will find an input field called <strong>Extra CSS Class for the table</strong>, <strong>add</strong> this class <strong>nt_has_lightbox</strong> here. <img src="https://ninjatables.com/wp-content/uploads/2022/10/table-design-02-scaled.webp" alt=""></p></li><li><p>Lastly, click on the <strong>Save</strong> button to save the settings. Now if you preview the table, the links from Google Sheets will have transformed into image and will open in a lightbox. Easily transform image link from Google Sheets into image lightbox in Ninja Tables this way.</p></li></ul>',17)])])}const m=t(n,[["render",l]]);export{k as __pageData,m as default};
